<link rel="stylesheet" href="/assets/admin-crud.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/admin-crud.css'))?>"><div class="crud-heading"><div><p>LOKET</p><h1>Kelola loket</h1></div></div><?php if(isset($_GET['saved'])):?><p class="ok crud-message">Pengaturan loket tersimpan.</p><?php elseif(isset($_GET['deleted'])):?><p class="ok crud-message">Loket berhasil dihapus.</p><?php elseif(isset($_GET['error'])):?><p class="alert crud-message"><?=e(match($_GET['error']){'has_history'=>'Loket tidak dapat dihapus karena sudah memiliki riwayat antrean. Nonaktifkan loket untuk mempertahankan laporan.','assigned_user'=>'Loket masih digunakan oleh pengguna operator. Ubah penugasan pengguna terlebih dahulu.','not_found'=>'Loket tidak ditemukan.',default=>'Loket tidak dapat dihapus.'})?></p><?php endif?><div class="grid2 crud-grid"><section class="card"><h2 id="counter-form-title">Tambah loket</h2><form method="post" id="counter-form"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="counter-id"><label>Nama loket<input name="name" id="counter-name" placeholder="Loket PTK" required></label><label>Kode<input name="code" id="counter-code" maxlength="20" placeholder="PTK" required></label><fieldset><legend>Layanan yang dilayani</legend><div class="check-grid"><?php foreach($services as $service):?><label><input type="checkbox" name="service_ids[]" value="<?=e($service['id'])?>"> <?=e($service['name'])?></label><?php endforeach?></div></fieldset><label class="media-check"><input type="checkbox" name="active" id="counter-active" checked> Aktif</label><button type="submit">Simpan loket</button><button type="button" class="secondary" id="counter-reset">Loket baru</button></form></section><section class="crud-table-card"><div class="crud-table-wrap"><table><thead><tr><th>Kode</th><th>Loket</th><th>Layanan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($counters as $counter):?><tr><td><b><?=e($counter['code'])?></b></td><td><?=e($counter['name'])?></td><td><?=e($counter['service_names']??'-')?></td><td><span class="crud-status <?=$counter['active']?'is-active':'is-inactive'?>"><?=$counter['active']?'Aktif':'Nonaktif'?></span></td><td><div class="crud-actions"><button type="button" class="edit-counter secondary" data-counter='<?=e(json_encode(['id'=>$counter['id'],'name'=>$counter['name'],'code'=>$counter['code'],'active'=>(bool)$counter['active'],'services'=>array_map('intval',explode(',',$counter['service_ids']??''))],JSON_UNESCAPED_UNICODE))?>'>Edit</button><form method="post" class="delete-form" data-name="<?=e($counter['name'])?>"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($counter['id'])?>"><button type="submit" class="danger">Hapus</button></form></div></td></tr><?php endforeach?></tbody></table></div></section></div><script src="/assets/counters.js?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/counters.js'))?>"></script><script src="/assets/admin-crud.js?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/admin-crud.js'))?>"></script>
